from taf.config.testline.legacy.configuration import Host
import os


class CbtsModel(object):
    """ This model allows to access crucial variables directly, without
    knowledge of nested and complicated configuration structure. It also
    provides consistent variable names, even if source variable is moved
    because of some architecture changes, it will be still accessible in
    CbtsModel with the same variable name. """
    def __init__(self, heat_stacks=None, mapper=None, cfg_dir=None, resource_registry=None,
                 bts_yaml='config_bts.yaml', net_yaml='config_ext_net.yaml', flavors_yaml='config_flavor.yaml'):

        self.flavor_name = None
        self.net_name = None
        self.bts_name = None
        self.vnf_prefix = None
        self.resource_registry = resource_registry
        self.cfg_dir = cfg_dir
        self.bts_yaml = os.path.join(cfg_dir, bts_yaml) if cfg_dir else None
        self.net_yaml = os.path.join(cfg_dir, net_yaml) if cfg_dir else None
        self.flavors_yaml = os.path.join(cfg_dir, flavors_yaml) if cfg_dir else None

        self._mapper = mapper
        self.heat = heat_stacks
        self.vnf_name = self._mapper.get_value('vnf_name') if mapper else None
        oam_ip = self._mapper.get_value('oam_ip') if mapper else None
        self.oam = self._create_host(oam_ip)

    def _create_host(self, ip):
        return Host(addr=ip, username=None, password=None)
